package main
const page = `<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Alpha Experiment 01</title><style>
*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 70% 0%,#263b5a,#090d16 55%);color:#f4f6ff;font:15px Segoe UI,system-ui,sans-serif}header{display:flex;justify-content:space-between;align-items:center;padding:26px 5vw;border-bottom:1px solid #394052}header b{font-size:23px}main{max-width:1450px;margin:auto;padding:30px 5vw}.muted{color:#a9b7ce}.eyebrow{color:#79d4ff;letter-spacing:2px;font-size:12px;text-transform:uppercase}h1{font-size:30px}#cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,350px),1fr));gap:24px}.card{background:#161e2e;color:inherit;text-align:left;border:1px solid #364257;border-radius:16px;overflow:hidden;font:inherit;cursor:pointer;padding:0}.card:hover,.card:focus-visible{border-color:#78caff;outline:none;transform:translateY(-3px)}.poster{height:205px;display:grid;place-items:center;background:linear-gradient(130deg,#1c4b6b,#131629);position:relative}.poster.teams{background:linear-gradient(130deg,#513169,#112944)}.poster .symbol{font-size:73px;color:#a0dfff}.tag{border:1px solid #586c84;border-radius:22px;padding:5px 10px;display:inline-block;font-size:12px;color:#dce7f9}.poster .tag{position:absolute;bottom:14px;left:14px;background:#0a1423e6}.pad{padding:22px}.pad h2{margin:0}.pad p{word-break:break-word}.panel{background:#121a29;border:1px solid #354157;border-radius:12px;padding:20px;overflow:hidden}.cols{display:grid;grid-template-columns:1.5fr 1fr;gap:20px}@media(max-width:800px){.cols{grid-template-columns:1fr}}#workspace{display:none}button.nav,a.nav{background:#263957;color:white;border:1px solid #527294;border-radius:8px;padding:10px 14px;text-decoration:none;font:inherit;cursor:pointer}a{color:#90d6ff}.bar{display:flex;gap:12px;flex-wrap:wrap;align-items:center;margin:20px 0}pre{font:12px Consolas,monospace;white-space:pre-wrap;overflow-wrap:anywhere;max-height:370px;overflow:auto;background:#080e18;padding:15px}#shot{width:100%;aspect-ratio:16/9;object-fit:contain;background:#0a111c;border-radius:8px}
</style><header><b>◈ PROJECT HUB <span class="muted">/ alpha-experment01</span></b><span class="tag">EXPERIMENT</span></header><main><section id="library"><p class="eyebrow">Your GitHub projects</p><h1>Project Library</h1><p class="muted" id="notice">Loading…</p><div id="cards"></div></section><section id="workspace"><div class="bar"><button class="nav" id="back">← All projects</button><h1 id="heading"></h1><span id="status" class="tag"></span></div><div class="cols"><div class="panel"><h2>Alpha Workspace</h2><img id="shot" alt="Live browser sample preview"><p id="preview" class="muted"></p><div class="bar"><a class="nav" id="alphaLink" href="http://127.0.0.1:18777/" target="_blank" rel="noopener">Open Alpha ↗</a><a class="nav" id="repoLink" target="_blank" rel="noopener">GitHub repo ↗</a></div></div><div class="panel"><h2>Project details</h2><div id="metadata"></div><h3>Logs</h3><pre id="logs">No runtime logs connected</pre></div></div></section></main>
<script>
const $=s=>document.querySelector(s);let data=null,selected=null,n=0;
function safe(s){return String(s==null?"":s).replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]))}
async function get(url,text){const r=await fetch(url,{cache:"no-store"});if(!r.ok)throw Error("HTTP "+r.status);return text?r.text():r.json()}
function label(p){return p.id==="dashboard"?(data.alphaOnline?"Alpha server running":"Alpha offline"):"Runtime not connected"}
function render(){if(!data)return;$("#notice").textContent="2 registered repositories • local runtime status where available";$("#cards").innerHTML=data.projects.map(p=>'<button class="card" data-id="'+safe(p.id)+'"><div class="poster '+safe(p.id)+'"><span class="symbol">'+(p.id==="dashboard"?"▣":"◎")+'</span><span class="tag">'+safe(label(p))+'</span></div><div class="pad"><h2>'+safe(p.name)+'</h2><p class="muted">'+safe(p.repo)+'</p><small class="muted">'+safe(p.local?("Local: "+(p.branch||"unknown")+" · "+(p.commit||"unknown")):"Local checkout not detected")+'</small></div></button>').join("");document.querySelectorAll(".card").forEach(b=>b.onclick=()=>{selected=b.dataset.id;show()});if(selected)show()}
function show(){let p=data.projects.find(x=>x.id===selected);if(!p)return;$("#library").style.display="none";$("#workspace").style.display="block";$("#heading").textContent=p.name;$("#status").textContent=label(p);$("#repoLink").href=p.repo;$("#metadata").innerHTML="<p><strong>Repository</strong><br>"+safe(p.repo)+"</p><p><strong>Path</strong><br>"+safe(p.local?p.path:"Not found")+"</p><p><strong>Branch</strong><br>"+safe(p.branch||"Unknown")+"</p><p><strong>Commit</strong><br>"+safe(p.commit||"Unknown")+"</p>";let active=p.id==="dashboard"&&data.alphaOnline;$("#alphaLink").style.display=active?"inline-block":"none";$("#shot").style.display="none";$("#preview").textContent=p.id==="teams"?"Teams registered. No runtime or live preview has been connected yet.":active?"Connected to Dashboard Alpha. The screenshot is its sample browser, not the Dashboard application itself.":"Dashboard Alpha offline. Start existing Alpha on port 18777.";$("#logs").textContent="No runtime logs connected";if(active)live()}
async function live(){if(selected!=="dashboard"||!data.alphaOnline)return;try{let s=await get("/api/alpha/state");let p=(s.projects||[]).find(x=>x.id==="owner-alpha-smoke");$("#status").textContent=p?"Alpha running · sample "+p.state:"Alpha running · sample absent";if(p&&p.state==="running"){$("#shot").src="/api/alpha/shot?t="+(++n);$("#shot").style.display="block"}else $("#shot").style.display="none";$("#logs").textContent=await get("/api/alpha/log",true)||"No sample logs yet"}catch(e){$("#logs").textContent="Alpha details unavailable: "+e.message}}
$("#back").onclick=()=>{selected=null;$("#workspace").style.display="none";$("#library").style.display="block"};
async function refresh(){try{data=await get("/api/projects");render()}catch(e){$("#notice").textContent="Local project service not available: "+e.message}}refresh();setInterval(refresh,5000);
</script></html>`
